This requires using C++20 with a standard library with std::format support.

"logging"_test = [] {  log("\npre {} == {}\n", 42, 43);  expect(42_i == 43) {}\n", 42, 43, 42 == 43); };

Running "logging"... pre 42 == 43  logging.cpp:8:FAILED [42 == 43] message on failure post 42 == 43 -> false FAILED

tests: 1 | 1 failed asserts: 1 | 0 passed | 1 failed

https://godbolt.org/z/26fPSY

&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Matchers

"matchers"_test = [] {  constexpr auto is_between = [](auto lhs, auto rhs) {  return [=] auto value {  return that % value >= lhs and that % value <= rhs;  };  };

expect(is_between(1, 100)(42));  expect(not is_between(1, 100)(0)); };

All tests passed (2 asserts in 1 tests)

https://godbolt.org/z/4qwrCi

&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Exceptions/Aborts

"exceptions/aborts"_test = [] {  expect(throws([] { throw std::runtime_error{""}; }))  https://godbolt.org/z/A2EehK

