namespace cfg {  class runner {  public:  template auto on(ut::events::test test) { test(); }  template auto on(ut::events::skip) {}  template   auto on(ut::events::assertion) -> bool { return true; }  auto on(ut::events::fatal_assertion) {}  template auto on(ut::events::log) {}  }; } // namespace cfg

template<> auto ut::cfg = cfg::runner{};

https://godbolt.org/z/jdg687

