NetCDF2LittleR only supports NetCDF files with a structure according to (for a single observation station):

netcdf test_1d { dimensions:  time = UNLIMITED ; // (10 currently)  lon = 1 ;  lat = 1 ;  elevation = 1 ; variables:  int time(time) ;  time:_FillValue = -999 ;  time:units = "seconds since 2010-01-01 00:00" ;  time:calendar = "standard" ;  time:timezone = "UTC" ;  float lat(lat) ;  lat:units = "degrees_north" ;  lat:cell_methods = "device: mean" ;  float lon(lon) ;  lon:units = "degrees_east" ;  lon:cell_methods = "device: mean" ;  float elevation(elevation) ;  elevation:units = "meter" ;  elevation:standard_name = "elevation" ;  float temperature(time) ;  temperature:_FillValue = -999.99f ;  temperature:units = "degC" ;  temperature:coordinates = "lat lon" ;  temperature:cell_methods = "point device: mean" ;  float humidity(time) ;  humidity:_FillValue = -999.99f ;  humidity:units = "1" ;  humidity:coordinates = "lat lon" ;  humidity:cell_methods = "point device: mean" ;

